OVERRIDES = {'parlay_bot.discord_app.home': '', 'parlay_bot.discord_app.opportunities': '', 'parlay_bot.discord_app.signals': '', 'parlay_bot.discord_app.status_card': '', 'parlay_bot.discord_app.research_alerts': ''}
"""Read-only: render the new (unmerged) wording against live data.

The new versions of a few display modules are loaded in memory for this one
process only; nothing on the host is written or changed.
"""
import asyncio, base64, gzip, importlib.abc, importlib.util, json, os, sys
from datetime import UTC, datetime, timedelta

MARKER = "RIVAL_RENDER_PROBE="


class _Override(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    def find_spec(self, name, path, target=None):
        if name in OVERRIDES:
            return importlib.util.spec_from_loader(name, self, origin="override:" + name)
        return None

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        src = gzip.decompress(base64.b64decode(OVERRIDES[module.__name__])).decode()
        exec(compile(src, module.__name__.replace(".", "/") + ".py", "exec"), module.__dict__)


sys.meta_path.insert(0, _Override())


def _dump(embed):
    return {"title": embed.title, "description": embed.description,
            "fields": [[f.name, f.value, f.inline] for f in embed.fields],
            "footer": embed.footer.text if embed.footer else None,
            "color": embed.color.value if embed.color else None}


async def _run():
    from types import SimpleNamespace

    from parlay_bot.config import Settings
    from parlay_bot.discord_app import error_log
    from parlay_bot.discord_app.home import GuidedHome
    from parlay_bot.discord_app.opportunities import crypto_desk_embed
    from parlay_bot.discord_app.research_alerts import research_alerts
    from parlay_bot.discord_app.signals import signal_embed
    from parlay_bot.discord_app.status_card import StatusFacts, build_embed
    from parlay_bot.perpetuals.live_quotes import PublicBestQuoteClient
    from parlay_bot.perpetuals.market_store import PerpetualMarketStore
    from parlay_bot.perpetuals.polymarket_research import PolymarketResearch
    from parlay_bot.storage.hot import PostgresHotStore

    out = {}
    store = PostgresHotStore(Settings().rival_database_url.get_secret_value())
    quotes = PublicBestQuoteClient()
    try:
        market = PerpetualMarketStore(store)
        with store.connect() as conn:
            venues = tuple(sorted({str(r["venue"]) for r in conn.execute(
                "SELECT DISTINCT venue FROM perp_forward_audit WHERE issued_at>=?",
                ("2026-11-01",)).fetchall()}))
        poly = PolymarketResearch(store, ai=None)
        poly.initialize()
        dummy = SimpleNamespace()
        for page, horizon in (("home", 5), ("help", 5), ("advanced", 5),
                              ("performance", 5), ("performance", 15)):
            home = GuidedHome(owner_id=1, location=dummy, builder=dummy, collector=None,
                              market=market, targets=dummy, paper=dummy, quotes=dummy,
                              profit=None, venues=venues,
                              polymarket_status=lambda a, h: poly.learner.summary(asset=a, horizon=h))
            home.coin, home.horizon = "BTC", horizon
            home.navigate(page)
            home._buttons()
            key = f"{page}/{horizon}" if page == "performance" else page
            try:
                await asyncio.wait_for(home.render(), timeout=60)
                out[key] = _dump(await asyncio.wait_for(home.render(), timeout=60))
                out[key]["buttons"] = [getattr(c, "label", None) or getattr(c, "placeholder", "")
                                       for c in home.children]
            except Exception as exc:  # noqa: BLE001
                out[key] = {"error": f"{type(exc).__name__}: {str(exc)[:200]}"}
            finally:
                home.stop()
        for proof in (False, True):
            try:
                out[f"desk/{proof}"] = _dump(crypto_desk_embed(market, asset="BTC", proof=proof))
            except Exception as exc:  # noqa: BLE001
                out[f"desk/{proof}"] = {"error": f"{type(exc).__name__}: {exc}"[:200]}
        for horizon in (5, 15):
            try:
                out[f"signal/{horizon}"] = _dump(await asyncio.wait_for(
                    signal_embed(market, quotes, asset="BTC", horizon_minutes=horizon), 60))
            except Exception as exc:  # noqa: BLE001
                out[f"signal/{horizon}"] = {"error": f"{type(exc).__name__}: {exc}"[:200]}
        # Status card: real prediction checks, feed health and logged problems;
        # jobs, streams and memory are sample values (they live in the bot process).
        now = datetime.now(UTC)
        try:
            research = await asyncio.to_thread(research_alerts, store, now=now)
        except Exception as exc:  # noqa: BLE001
            research = [("probe", f"(probe could not run checks: {type(exc).__name__})")]
        try:
            feeds = market.feed_health()
        except Exception:  # noqa: BLE001
            feeds = None
        try:
            problems, totals = error_log.RecentProblems().stored(store)
        except Exception:  # noqa: BLE001
            problems, totals = [], {}
        facts = StatusFacts(
            now=now, boot_at=now - timedelta(hours=2, minutes=10), ready=True,
            heartbeat={"last_success_at": now - timedelta(seconds=40), "consecutive_problems": 0},
            workers=[{"name": f"job{i}", "state": "running"} for i in range(12)],
            incidents=[], feeds=feeds,
            streams={"hyperliquid": {"connected": True, "updates": 48211, "reconnects": 1,
                                     "last_update_age_s": 3, "fresh_assets": ("BTC",)},
                     "bybit": {"connected": True, "updates": 39102, "reconnects": 0,
                               "last_update_age_s": 2, "fresh_assets": ("BTC",)}},
            liquidity_last_bucket=(now - timedelta(minutes=3)).isoformat(),
            memory={"rss_mb": 412, "limit_mb": 1282}, problems=problems,
            problem_totals=totals, research=research)
        out["status"] = _dump(build_embed(facts)[0])
    finally:
        try:
            await quotes.aclose()
        except Exception:  # noqa: BLE001
            pass
        store.close()
    return out


try:
    report = asyncio.run(_run())
except Exception as exc:  # noqa: BLE001 - never print DSN or SQL
    report = {"error": f"{type(exc).__name__}: {str(exc)[:300]}"}
print(MARKER + base64.b64encode(gzip.compress(json.dumps(report, default=str).encode())).decode())
